"use client";
import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { API } from "@/utils/api";
import {
  LogOut,
  Bell,
  Plus,
  FileText,
  CheckCircle,
  Users,
  Clock,
  UtensilsCrossed,
  LayoutGrid
} from "lucide-react";

export default function StaffHome() {
  const router = useRouter();
  const [staff, setStaff] = useState(null);
  const [tables, setTables] = useState([]);
  const [stats, setStats] = useState({
    occupied: 0,
    free: 0,
    pending: 0,
    ready: 0
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const checkAuth = async () => {
      const token = localStorage.getItem("staffToken");
      const staffUser = localStorage.getItem("staffUser");

      if (!token || !staffUser) {
        router.push("/business/staff/login");
        return;
      }

      try {
        const response = await API.get("/api/business/staff/profile", {
          headers: { Authorization: `Bearer ${token}` }
        });
        setStaff(response.data.staff);
        fetchTablesAndOrders(token);
      } catch (error) {
        console.error("Auth error:", error);
        if (error.response?.status === 401) {
          localStorage.removeItem("staffToken");
          localStorage.removeItem("staffUser");
          router.push("/business/staff/login");
        }
      }
    };

    checkAuth();
  }, [router]);

  const fetchTablesAndOrders = async (token) => {
    try {
      const [tablesRes, ordersRes] = await Promise.all([
        API.get("/api/business/tables", {
          headers: { Authorization: `Bearer ${token}` }
        }),
        API.get("/api/business/orders", {
          headers: { Authorization: `Bearer ${token}` }
        })
      ]);

      const tablesData = tablesRes.data.tables || [];
      setTables(tablesData);

      // Calculate stats
      const occupied = tablesData.filter(t => t.status === "occupied").length;
      const free = tablesData.filter(t => t.status === "free").length;
      const pending = ordersRes.data.orders?.filter(o => o.status === "pending").length || 0;
      const ready = ordersRes.data.orders?.filter(o => o.status === "ready").length || 0;

      setStats({ occupied, free, pending, ready });
      setLoading(false);
    } catch (error) {
      console.error("Error fetching data:", error);
      setLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("staffToken");
    localStorage.removeItem("staffUser");
    router.push("/business/staff/login");
  };

  const getTableColor = (status) => {
    switch (status) {
      case "free": return "bg-emerald-50 border-emerald-200 hover:border-emerald-400";
      case "occupied": return "bg-rose-50 border-rose-200 hover:border-rose-400";
      case "waiting_bill": return "bg-amber-50 border-amber-200 hover:border-amber-400";
      case "order_in_progress": return "bg-blue-50 border-blue-200 hover:border-blue-400";
      default: return "bg-gray-50 border-gray-200 hover:border-gray-400";
    }
  };

  const getTableBadgeColor = (status) => {
    switch (status) {
      case "free": return "bg-emerald-500";
      case "occupied": return "bg-rose-500";
      case "waiting_bill": return "bg-amber-500";
      case "order_in_progress": return "bg-blue-500";
      default: return "bg-gray-500";
    }
  };

  const getTimeSince = (timestamp) => {
    if (!timestamp) return "—";
    const minutes = Math.floor((Date.now() - new Date(timestamp)) / 60000);
    if (minutes < 60) return `${minutes}m`;
    return `${Math.floor(minutes / 60)}h ${minutes % 60}m`;
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-[#C9A050] border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-gray-600 font-medium">Loading Dashboard...</p>
        </div>
      </div>
    );
  }

  const currentHour = new Date().getHours();
  const shift = currentHour < 16 ? "Morning" : currentHour < 20 ? "Evening" : "Night";

  return (
    <div className="min-h-screen bg-[#F9FAFB]">
      {/* HEADER */}
      <header className="bg-white border-b border-gray-100 sticky top-0 z-50">
        <div className="container mx-auto px-4 py-4">
          <div className="flex items-center justify-between">
            {/* Left: Greeting */}
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-gradient-to-br from-[#C9A050] to-[#E5C575] rounded-full flex items-center justify-center text-white font-bold text-xl shadow-md">
                {staff?.name?.charAt(0) || "S"}
              </div>
              <div>
                <h1 className="text-xl font-bold text-gray-900">
                  {staff?.name || "Staff Member"}
                </h1>
                <p className="text-xs text-gray-500 flex items-center gap-2">
                  <span className="inline-block w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                  {shift} Shift • {new Date().toLocaleTimeString('en-US', {
                    hour: '2-digit',
                    minute: '2-digit'
                  })}
                </p>
              </div>
            </div>

            {/* Right: Actions */}
            <div className="flex items-center gap-3">
              <button className="relative p-2.5 bg-gray-50 hover:bg-gray-100 rounded-xl transition-all text-gray-600 hover:text-[#C9A050]">
                <Bell className="w-5 h-5" />
                <span className="absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span>
              </button>
              <button
                onClick={handleLogout}
                className="flex items-center gap-2 px-4 py-2.5 bg-white border border-gray-200 hover:border-red-200 hover:bg-red-50 text-gray-700 hover:text-red-600 rounded-xl transition-all text-sm font-medium"
              >
                <LogOut className="w-4 h-4" />
                <span className="hidden sm:inline">Logout</span>
              </button>
            </div>
          </div>
        </div>
      </header>

      <div className="container mx-auto px-4 py-8 space-y-8">

        {/* WELCOME BANNER */}
        <div className="bg-gradient-to-r from-[#1F2937] to-[#374151] rounded-2xl p-6 text-white shadow-xl relative overflow-hidden">
          <div className="absolute top-0 right-0 w-64 h-64 bg-[#C9A050] opacity-10 rounded-full blur-3xl transform translate-x-1/2 -translate-y-1/2"></div>
          <div className="relative z-10 flex flex-col sm:flex-row justify-between items-center gap-4">
            <div>
              <h2 className="text-2xl font-bold mb-1">Restaurant Overview</h2>
              <p className="text-gray-300 text-sm">Here's what's happening in the restaurant right now.</p>
            </div>
            <div className="flex gap-4">
              <div className="text-center px-4 py-2 bg-white/10 rounded-lg backdrop-blur-sm">
                <p className="text-xs text-gray-300 uppercase tracking-wider">Total Tables</p>
                <p className="text-2xl font-bold text-[#C9A050]">{tables.length}</p>
              </div>
            </div>
          </div>
        </div>

        {/* OVERVIEW STATS */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 hover:shadow-md transition-shadow">
            <div className="flex items-center justify-between mb-3">
              <div className="w-10 h-10 bg-emerald-50 rounded-xl flex items-center justify-center">
                <Users className="w-5 h-5 text-emerald-600" />
              </div>
              <span className="text-xs font-medium text-emerald-600 bg-emerald-50 px-2 py-1 rounded-full">Available</span>
            </div>
            <p className="text-3xl font-bold text-gray-900">{stats.free}</p>
            <p className="text-sm text-gray-500 mt-1">Free Tables</p>
          </div>

          <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 hover:shadow-md transition-shadow">
            <div className="flex items-center justify-between mb-3">
              <div className="w-10 h-10 bg-rose-50 rounded-xl flex items-center justify-center">
                <UtensilsCrossed className="w-5 h-5 text-rose-600" />
              </div>
              <span className="text-xs font-medium text-rose-600 bg-rose-50 px-2 py-1 rounded-full">Busy</span>
            </div>
            <p className="text-3xl font-bold text-gray-900">{stats.occupied}</p>
            <p className="text-sm text-gray-500 mt-1">Occupied Tables</p>
          </div>

          <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 hover:shadow-md transition-shadow">
            <div className="flex items-center justify-between mb-3">
              <div className="w-10 h-10 bg-amber-50 rounded-xl flex items-center justify-center">
                <Clock className="w-5 h-5 text-amber-600" />
              </div>
              <span className="text-xs font-medium text-amber-600 bg-amber-50 px-2 py-1 rounded-full">Waiting</span>
            </div>
            <p className="text-3xl font-bold text-gray-900">{stats.pending}</p>
            <p className="text-sm text-gray-500 mt-1">Pending Orders</p>
          </div>

          <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 hover:shadow-md transition-shadow">
            <div className="flex items-center justify-between mb-3">
              <div className="w-10 h-10 bg-blue-50 rounded-xl flex items-center justify-center">
                <CheckCircle className="w-5 h-5 text-blue-600" />
              </div>
              <span className="text-xs font-medium text-blue-600 bg-blue-50 px-2 py-1 rounded-full">Ready</span>
            </div>
            <p className="text-3xl font-bold text-gray-900">{stats.ready}</p>
            <p className="text-sm text-gray-500 mt-1">To Serve</p>
          </div>
        </div>

        {/* QUICK ACTIONS */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <button
            onClick={() => router.push("/business/staff/new-order")}
            className="group relative overflow-hidden bg-white p-6 rounded-2xl shadow-sm border border-gray-100 hover:border-[#C9A050] transition-all text-left"
          >
            <div className="absolute top-0 right-0 w-24 h-24 bg-[#C9A050] opacity-5 rounded-full blur-2xl transform translate-x-1/2 -translate-y-1/2 group-hover:opacity-10 transition-opacity"></div>
            <div className="w-12 h-12 bg-[#C9A050] text-white rounded-xl flex items-center justify-center mb-4 shadow-lg shadow-[#C9A050]/20 group-hover:scale-110 transition-transform">
              <Plus className="w-6 h-6" />
            </div>
            <h3 className="text-lg font-bold text-gray-900 group-hover:text-[#C9A050] transition-colors">Take New Order</h3>
            <p className="text-sm text-gray-500 mt-1">Start a new order for a table</p>
          </button>

          <button
            onClick={() => router.push("/business/staff/active-orders")}
            className="group relative overflow-hidden bg-white p-6 rounded-2xl shadow-sm border border-gray-100 hover:border-blue-500 transition-all text-left"
          >
            <div className="absolute top-0 right-0 w-24 h-24 bg-blue-500 opacity-5 rounded-full blur-2xl transform translate-x-1/2 -translate-y-1/2 group-hover:opacity-10 transition-opacity"></div>
            <div className="w-12 h-12 bg-blue-500 text-white rounded-xl flex items-center justify-center mb-4 shadow-lg shadow-blue-500/20 group-hover:scale-110 transition-transform">
              <FileText className="w-6 h-6" />
            </div>
            <h3 className="text-lg font-bold text-gray-900 group-hover:text-blue-600 transition-colors">Active Orders</h3>
            <p className="text-sm text-gray-500 mt-1">View and manage ongoing orders</p>
          </button>

          <button
            onClick={() => router.push("/business/staff/ready-orders")}
            className="group relative overflow-hidden bg-white p-6 rounded-2xl shadow-sm border border-gray-100 hover:border-emerald-500 transition-all text-left"
          >
            <div className="absolute top-0 right-0 w-24 h-24 bg-emerald-500 opacity-5 rounded-full blur-2xl transform translate-x-1/2 -translate-y-1/2 group-hover:opacity-10 transition-opacity"></div>
            <div className="w-12 h-12 bg-emerald-500 text-white rounded-xl flex items-center justify-center mb-4 shadow-lg shadow-emerald-500/20 group-hover:scale-110 transition-transform">
              <CheckCircle className="w-6 h-6" />
            </div>
            <h3 className="text-lg font-bold text-gray-900 group-hover:text-emerald-600 transition-colors">Ready to Serve</h3>
            <p className="text-sm text-gray-500 mt-1">Orders ready for pickup</p>
          </button>
        </div>

        {/* LIVE TABLE MAP */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-[#C9A050]/10 rounded-lg">
                <LayoutGrid className="w-6 h-6 text-[#C9A050]" />
              </div>
              <div>
                <h2 className="text-xl font-bold text-gray-900">Live Floor Plan</h2>
                <p className="text-sm text-gray-500">Real-time table status updates</p>
              </div>
            </div>

            <div className="flex flex-wrap gap-3 text-xs font-medium bg-gray-50 p-2 rounded-xl">
              <div className="flex items-center gap-2 px-3 py-1.5 bg-white rounded-lg shadow-sm border border-gray-100">
                <div className="w-2.5 h-2.5 bg-emerald-500 rounded-full"></div>
                <span className="text-gray-700">Free</span>
              </div>
              <div className="flex items-center gap-2 px-3 py-1.5 bg-white rounded-lg shadow-sm border border-gray-100">
                <div className="w-2.5 h-2.5 bg-rose-500 rounded-full"></div>
                <span className="text-gray-700">Occupied</span>
              </div>
              <div className="flex items-center gap-2 px-3 py-1.5 bg-white rounded-lg shadow-sm border border-gray-100">
                <div className="w-2.5 h-2.5 bg-amber-500 rounded-full"></div>
                <span className="text-gray-700">Bill</span>
              </div>
              <div className="flex items-center gap-2 px-3 py-1.5 bg-white rounded-lg shadow-sm border border-gray-100">
                <div className="w-2.5 h-2.5 bg-blue-500 rounded-full"></div>
                <span className="text-gray-700">Ordering</span>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-4">
            {tables.map((table) => (
              <div
                key={table._id}
                onClick={() => router.push(`/business/staff/table/${table._id}`)}
                className={`
                  relative group cursor-pointer transition-all duration-300
                  ${getTableColor(table.status)}
                  border-2 rounded-2xl p-4
                  hover:shadow-lg hover:-translate-y-1
                `}
              >
                {/* Status Badge */}
                <div className={`absolute top-3 right-3 w-3 h-3 ${getTableBadgeColor(table.status)} rounded-full ring-4 ring-white/50`}></div>

                {/* Table Number */}
                <div className="flex flex-col items-center justify-center py-4">
                  <span className="text-xs font-bold uppercase tracking-wider text-gray-500 mb-1">Table</span>
                  <span className="text-3xl font-black text-gray-800">{table.tableNumber}</span>
                </div>

                {/* Table Info */}
                <div className="space-y-2 pt-3 border-t border-gray-200/50">
                  <div className="flex items-center justify-between text-xs">
                    <span className="text-gray-500 flex items-center gap-1">
                      <Users className="w-3 h-3" /> Guests
                    </span>
                    <span className="font-bold text-gray-700">{table.guests || "-"}</span>
                  </div>
                  <div className="flex items-center justify-between text-xs">
                    <span className="text-gray-500 flex items-center gap-1">
                      <Clock className="w-3 h-3" /> Time
                    </span>
                    <span className="font-bold text-gray-700">{getTimeSince(table.seatedAt)}</span>
                  </div>
                </div>

                {/* Hover Action */}
                <div className="absolute inset-0 bg-black/5 opacity-0 group-hover:opacity-100 transition-opacity rounded-2xl flex items-center justify-center backdrop-blur-[1px]">
                  <span className="bg-white text-gray-900 px-4 py-2 rounded-lg font-bold text-sm shadow-lg transform scale-90 group-hover:scale-100 transition-transform">
                    View Details
                  </span>
                </div>
              </div>
            ))}
          </div>

          {tables.length === 0 && (
            <div className="text-center py-12 bg-gray-50 rounded-2xl border-2 border-dashed border-gray-200">
              <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <LayoutGrid className="w-8 h-8 text-gray-400" />
              </div>
              <h3 className="text-lg font-bold text-gray-900">No Tables Found</h3>
              <p className="text-gray-500 text-sm mt-1">There are no tables configured for this restaurant yet.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}